"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3523],{2045(e){e.exports=JSON.parse('{"title":"\ud504\ub860\ud2b8\uc5d4\ub4dc \uc0dd\ud0dc\uacc4 \uc774\ub300\ub85c \uac00\uba74","date":"2025-03-27","coverUrl":"/kudzu-based-bench/assets/notion/69c0ba9eb0437e61.png","html":"<h2 data-notion-block-id=\\"1bfe548d-8a8e-80b8-a877-e4a75d1476b5\\" id=\\"1bfe548d-8a8e-80b8-a877-e4a75d1476b5\\">\ud504\ub860\ud2b8\uc5d4\ub4dc \uc0dd\ud0dc\uacc4 \uc774\ub300\ub85c \uac00\uba74</h2><a href=\\"https://polotek.net/posts/the-frontend-treadmill/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://polotek.net/posts/the-frontend-treadmill/</a><p data-notion-block-id=\\"1bfe548d-8a8e-806d-a035-fb30199d873d\\">\ud504\ub808\uc784\uc6cc\ud06c\uac00 \uc804\ub144\ub3c4\ubcf4\ub2e4 \ub354\uc6b1\ub354 \ubc94\ub78c\ud558\uace0 \uc788\ub294\ub370, \uc0c8\ub85c \ub098\uc624\ub294 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ubaa8\ub450 \ubc30\uc6b0\uae30\ubcf4\ub2e4 \ud575\uc2ec \uc6f9 \uae30\uc220\uc5d0 \uc9d1\uc911\ud558\uc790\ub294 \uc774\uc57c\uae30\ub97c \ub2f4\uc740 \uae00\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/30480561-d12b-484b-9886-1eafeb5b6d35#44319358-d78c-4227-950b-e11083ea5513\\">\ud504\ub860\ud2b8\uc5d4\ub4dc \uacfc\uac70\uc640 \ud604\uc7ac</a> \uae00\uc5d0\ub3c4 \ubcf4\uc774\ub4ef\uc774 \ubaa8\ub4e0 \uae30\uc220\uc5d0\ub294 \ubaa8\ub4e0 \uc774\uc720\uac00 \uc788\uae30\uc5d0, \ubaa8\ub450 \ubc30\uc6b0\ub824\uae30\ubcf4\ub2e4\ub294 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824 \ud588\ub294\uc9c0\ub97c \uc54c\uace0 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. <a href=\\"https://www.kylegill.com/essays/next-vs-tanstack/\\">Next.js\ub97c \uc120\ud0dd\ud558\uc9c0 \uc54a\uace0 Tanstack Router\ub97c \uc120\ud0dd\ud558\ub294 \uae00</a>\uc5d0\uc11c\ub3c4 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ud2b9\uc131\uc5d0 \ub530\ub77c \uae30\uc220\uc744 \uc120\ud0dd\ud558\ub294 \ubaa8\uc2b5\uc774 \ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-8070-bf77-dfd80485b38e\\" id=\\"1bfe548d-8a8e-8070-bf77-dfd80485b38e\\">inline Background, \uc5b4\ub514\uae4c\uc9c0 \uad6c\ud604\ud574\ubd24\ub2c8?</h2><a href=\\"http://frontendmasters.com/blog/overlapping-inline-backgrounds/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">http://frontendmasters.com/blog/overlapping-inline-backgrounds/</a><p data-notion-block-id=\\"1bfe548d-8a8e-8025-b22e-cd9ccdbbc485\\">inline background\ub97c background-color\ub97c \ud1b5\ud574\uc11c \uad6c\ud604\ud558\uba74, \uacb9\uce68 \ud604\uc0c1\uc774 \ubc1c\uc0dd\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 svg \ud544\ud130\ub97c \ud1b5\ud574 \ubb38\uc81c \uc5c6\ub294 \ubc29\uc2dd\uc73c\ub85c \uad6c\ud604 \ud6c4 \uace0\ub3c4\ud654\ud558\uba74\uc11c, svg \ud544\ud130\uc640 \uad00\ub828\ub41c CSS \uc18d\uc131\uc744 \uc790\uc138\ud558\uac8c \uc54c\uc544\ubd05\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c2e548d-8a8e-805d-9b69-edeed701604f\\" id=\\"1c2e548d-8a8e-805d-9b69-edeed701604f\\">React \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640 React\uc758 \ud1b5\ud569 \uc774\ud574\ud558\uae30</h2><a href=\\"https://www.felgus.dev/blog/common-react-lib-architecture\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.felgus.dev/blog/common-react-lib-architecture</a><p data-notion-block-id=\\"1c2e548d-8a8e-80e3-b46d-f86c8edbbc42\\">\uc0c1\ud0dc\ub97c \ub2f4\ub2f9\ud558\ub294 \uc218\ub9ce\uc740 React \uae30\ubc18 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c React\uc640 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ud1b5\ud569\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uadf8 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uc5b4\ub5a4 \uc7a5\ub2e8\uc810\uc774 \uc788\ub294\uc9c0(<a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#aef423ee-c881-4803-a5c7-d940c6246140\\">\uc608\uc2dc</a>)\ub97c \ucc28\uadfc\ucc28\uadfc \uc124\uba85\ud569\ub2c8\ub2e4. \uc0c1\ud0dc\ub97c \ub2f4\ub2f9\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uac04\ub2e8\ud558\uc5ec \ubc84\uadf8\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc0ac\ub78c\uc77c\uc740 \ubaa8\ub974\uae30 \ub54c\ubb38\uc5d0 \uc5b4\ub5bb\uac8c \ud1b5\ud569\ud558\ub294\uc9c0 \uc544\ub294 \uac83\uc740 \uc911\uc694\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-8017-ac96-c347a2c48adf\\" id=\\"1bfe548d-8a8e-8017-ac96-c347a2c48adf\\">\uc5d0\ub514\ud130 \uac1c\ubc1c\uc790\uc758 \uc131\ub2a5 \ubb38\uc81c \uc811\uadfc \ubc29\uc2dd</h2><a href=\\"https://ckeditor.com/blog/how-we-made-our-rich-text-editor-load-faster-part-1/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ckeditor.com/blog/how-we-made-our-rich-text-editor-load-faster-part-1/</a><p data-notion-block-id=\\"1bfe548d-8a8e-80ba-8369-e2386f30d700\\">Rich Text Editor\uc778 CKEditor\uc5d0\uc11c \uc131\ub2a5 \ubb38\uc81c\ub97c \ud0d0\uc0c9\ud558\uace0, \ubb38\uc81c\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc131\ub2a5 \ubb38\uc81c\ub97c \ucc3e\ub294 \ubc29\uc2dd\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac \uac1c\ubc1c\uc790\uac00 \uc544\ub2c8\ub354\ub77c\ub3c4 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uac1c\ubc1c\uc790\uc5d0\uac8c\ub3c4 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \ub450\ubc88\uc9f8 \uae00\uc5d0\uc11c\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/8b8e4348-60f9-477e-9892-e7dfdf611fe0#b0fa8093-7010-49bd-9e12-b95e81fcacef\\">JS\uc5d4\uc9c4\uc758 monomorphism \uce90\uc2f1\uc744 \uc124\uba85\ud558\ub294 \uae00\ub4e4</a>\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-806c-9646-d5b9bcf1105b\\" id=\\"1bfe548d-8a8e-806c-9646-d5b9bcf1105b\\">ESLint v9\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud574\ubcf4\uc790.</h2><a href=\\"https://www.neoxs.me/blog/migration-to-eslint-v9\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.neoxs.me/blog/migration-to-eslint-v9</a><p data-notion-block-id=\\"1bfe548d-8a8e-804d-ad25-dc84b9a73d5c\\">ESLint\uac00 v9\ub85c \ubcc0\uacbd\ub418\uba74\uc11c \uc5ec\ub7ec \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ubcc0\uacbd\uc810, \uc124\uc815\uc758 \ubcc0\uacbd\uc810\uc73c\ub85c \uc778\ud574 \uc124\uc815\uc744 \ubc14\uafb8\uae30 \uc2dc\uc791\ud558\uae30 \uace4\ub780\ud560 \ub54c \uc5b4\ub5bb\uac8c \ud574\uc57c\ud558\ub294\uc9c0 \uac00\uc774\ub4dc\ub77c\uc778\uc774 \ub420 \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uc18c\uac1c\uc640 \ucc38\uace0 \ubb38\ud5cc\uc774 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc, <a href=\\"https://github.com/eslint/eslint/issues/18391\\">ESLint\uc758 v9 \uc9c0\uc6d0 \ud2b8\ub798\ud0b9 \uc774\uc288</a>\ub97c \ud1b5\ud574 \uc5ec\ub7ec \uc0c8\ub85c\uc6b4 plugin \ub77c\uc774\ube0c\ub7ec\ub9ac \ub3c4\uc785\uc744 \uac80\ud1a0\ud574\ubcf4\ub294 \uac83\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-80ae-a311-da196b44a7ee\\" id=\\"1bfe548d-8a8e-80ae-a311-da196b44a7ee\\">DB \ub300\uc2e0, \ub3d9\uae30\ud654\ud558\uc790.</h2><a href=\\"https://www.instantdb.com/essays/sync_future\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.instantdb.com/essays/sync_future</a><p data-notion-block-id=\\"1c2e548d-8a8e-8068-840a-ca546de6a90a\\">\ube0c\ub77c\uc6b0\uc800\uc758 IndexedDB \uae30\ub2a5\uc744 \uc774\uc6a9\ud558\uc5ec \ubc31\uc5d4\ub4dc \uc5c6\uc774 DB \ub3d9\uae30\ud654 \uc5d4\uc9c4\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \ubbf8\ub798\uac00 \ub420 \uc218\ub3c4 \uc788\uaca0\ub2e4\ub294 \uc2dc\uc120\uc744 \uacf5\uc720\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 \uc774\uc804\uc5d0 \uc18c\uac1c\ud55c <a href=\\"https://ones-to-watch.ethansup.net/news/post/11de548d-8a8e-80d0-9c96-f08026294b50#11de548d-8a8e-8009-a319-c31f78d0a4c5\\">Local-first \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158</a>\uc5d0\ub9cc \ubbf8\ub798\uac00 \ub420 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \ubbf8\ub798\ub294 \ubaa8\ub974\ub2c8\uae4c\uc694.</p><h2 data-notion-block-id=\\"1c2e548d-8a8e-808a-b034-f7eed2980b64\\" id=\\"1c2e548d-8a8e-808a-b034-f7eed2980b64\\">Parcel\uc758 RSC \uc9c0\uc6d0</h2><a href=\\"https://parceljs.org/blog/v2-14-0/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://parceljs.org/blog/v2-14-0/</a><p data-notion-block-id=\\"1c2e548d-8a8e-80ef-85b2-f8abb413bf58\\">RSC \uc9c0\uc6d0\uc740 \ub9e4\uc6b0 \ud55c\uc815\uc801\uc774\uc600\uc5c8\ub294\ub370, Parcel 2.14\ubc84\uc804\ubd80\ud130 \uc9c0\uc6d0\uc744 \uc2dc\uc791\ud574\uc11c, \uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4 \uc139\uc158 \ub4a4\uc5d0 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-80c8-ba45-d6d0d802d473\\" id=\\"1bfe548d-8a8e-80c8-ba45-d6d0d802d473\\">BreadCrumb\ub294 \uc65c \uc5c6\uc5b4\uc84c\uc744\uae4c</h2><a href=\\"https://webdesignerdepot.com/breadcrumbs-are-dead-in-web-design/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webdesignerdepot.com/breadcrumbs-are-dead-in-web-design/</a><p data-notion-block-id=\\"1bfe548d-8a8e-807b-bd06-f854f7e614bf\\">BreadCrumb\uac00 \ud604\ub300 \uc6f9 \ub514\uc790\uc778\uc5d0\uc11c \uc65c \uc0ac\ub77c\uc84c\ub294\uc9c0\uc5d0 \ub300\ud55c \uc8fc\uad00\uc801\uc778 \uc758\uacac\uc744 \uc801\uc740 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. \uac04\ub2e8\ud55c \uae00\uc774\uc9c0\ub9cc \uc65c \uadf8\ub7ac\ub294\uc9c0\uc5d0 \ub300\ud55c \uc774\uc720\uc640 \ub300\uccb4\ud488\ub4e4\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-8071-8864-f3fae1c5b709\\" id=\\"1bfe548d-8a8e-8071-8864-f3fae1c5b709\\">React \uac1c\ubc1c\uc790\uc5d0\uac8c SSR \uc124\uba85\ud558\uae30</h2><a href=\\"https://www.developerway.com/posts/ssr-deep-dive-for-react-developers\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.developerway.com/posts/ssr-deep-dive-for-react-developers</a><p data-notion-block-id=\\"1bfe548d-8a8e-8088-ab2c-f0e192f25082\\">SSR\uc774 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0\ub3c4 \uc124\uba85\ud558\uc9c0\ub9cc, \uadf8\ubcf4\ub2e4 SPA\uc5d0\uc11c SSR\uc774 \ud544\uc694\ud558\uac8c \ub41c \uacbd\uc6b0, \uba54\ud0c0\ud504\ub808\uc784\uc6cc\ud06c\uc758 \ub4f1\uc7a5, \uc11c\ubc84\ub9ac\uc2a4\uc758 \uc7a5\ub2e8\uc810\u2026\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 SSR\uc758 \ubc1c\uc804 \uacfc\uc815\uc744 \uac04\ub2e8\ud558\uac8c \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 \uc790\uc138\ud558\uace0 \uce5c\uc808\ud55c \uc124\uba85 \uae00\uc740 <a href=\\"https://www.patterns.dev/react/client-side-rendering/\\">patterns.dev\uc758 \ub80c\ub354\ub9c1 \ud328\ud134 \ubd80\ubd84</a>\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-8079-9364-da4cea06d3b7\\" id=\\"1bfe548d-8a8e-8079-9364-da4cea06d3b7\\">AWS Lambda\ub294 \uc5b4\ub5bb\uac8c \uc368\uc57c \ud560\uae4c</h2><a href=\\"https://aws.amazon.com/ko/blogs/compute/handling-billions-of-invocations-best-practices-from-aws-lambda/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aws.amazon.com/ko/blogs/compute/handling-billions-of-invocations-best-practices-from-aws-lambda/</a><p data-notion-block-id=\\"1bfe548d-8a8e-805e-90c5-dfdee5cdc3c1\\">AWS\uc5d0\uc11c AWS Lambda\uc5d0\uc11c \uc218\ub9ce\uc740 \ud638\ucd9c\uc744 \ucc98\ub9ac\ud558\uae30 \uc704\ud574 \uc5b4\ub5bb\uac8c \uc778\ud504\ub77c\ub97c \uad6c\uc131\ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubb3c\ub860 \uacbd\uc6b0\uc5d0 \ub530\ub77c<a href=\\"https://ones-to-watch.ethansup.net/news/post/3822cc46-45e8-4059-994b-1ab96c427c4c#15dd44ad-c3a4-4cbe-be4c-703e7927011d\\"> Edge Function\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uc744 \uc218\ub3c4</a> \uc788\uc73c\ub2c8, \uc798 \uace0\ub824\ud558\uace0 \ub3c4\uc785\uc744 \uac80\ud1a0\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"1bfe548d-8a8e-80b4-bd5a-dbaa9e1b1940\\" id=\\"1bfe548d-8a8e-80b4-bd5a-dbaa9e1b1940\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc5d0\ub294 \ub514\uc2a4\ud50c\ub808\uc774\uc5d0 \ub300\ud55c \uace0\ub824\uac00 \ud544\uc694\ud558\ub2e4</h2><a href=\\"https://bjango.com/articles/designsystemcolourspace/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bjango.com/articles/designsystemcolourspace/</a><p data-notion-block-id=\\"1bfe548d-8a8e-80aa-b26d-c79b1858d2c3\\">\uc0c9 \uacf5\uac04\uc774\ub77c\uace0 \uce6d\ud574\uc9c0\ub294 color space\ub294 \ub514\uc2a4\ud50c\ub808\uc774\ub9c8\ub2e4 \uc9c0\uc6d0\ubc29\uc2dd\uc774 \ub2e4\ub974\uace0, \uaddc\uaca9\ub610\ud55c \uc5ec\ub7ec\uac1c\uac00 \uc874\uc7ac\ud569\ub2c8\ub2e4. \uac00\uc7a5 \uc720\uba85\ud55c \uaddc\uaca9\uc778 P3\ub97c \uc18c\uac1c\ud558\uace0, \ube0c\ub77c\uc6b0\uc800 CSS\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc9c0\uc6d0\ud574\uc57c\ud558\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-80a0-a23d-d88950e39bd0\\" id=\\"1bfe548d-8a8e-80a0-a23d-d88950e39bd0\\">JS \uc545\uc131 \uc2a4\ud06c\ub9bd\ud2b8\ub97c AI\ub85c \ud0d0\uc9c0\ud558\uae30</h2><a href=\\"http://blog.cloudflare.com/how-we-train-ai-to-uncover-malicious-javascript-intent-and-make-web-surfing-safer/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">http://blog.cloudflare.com/how-we-train-ai-to-uncover-malicious-javascript-intent-and-make-web-surfing-safer/</a><p data-notion-block-id=\\"1bfe548d-8a8e-80d8-9061-ecbb65fc399a\\">AST \ub300\uc2e0 CST\ub85c \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\ub97c \ubd84\uc11d\ud558\uc5ec \uc545\uc131 \uc2a4\ud06c\ub9bd\ud2b8\uc5d0 \ud574\ub2f9\ub418\ub294 \ubd80\ubd84\uc744 \uc5b4\ub5bb\uac8c \ud0d0\uc9c0\ud558\ub3c4\ub85d \ud6c8\ub828\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub300\ubd80\ubd84\uc740 AI\uc758 \ud559\uc2b5\uacfc \ud3c9\uac00\uc5d0 \ub300\ud55c \ubd80\ubd84\uc774\uc9c0\ub9cc, JS\ub97c \ubd84\uc11d\ud558\ub294\uc9c0\uc5d0 \ub300\ud55c \ubd80\ubd84\uc740 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uac00 \ud559\uc2b5\ud558\uae30\uc5d0 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-8067-affe-fca8b6b49c4e\\" id=\\"1bfe548d-8a8e-8067-affe-fca8b6b49c4e\\">Flexbox\uc5d0\uc11c \uc77c\ubd80\ub9cc gap\uc744 \ubc14\uafd4\uc57c \ud560\ub54c</h2><a href=\\"https://ishadeed.com/article/self-gap/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/self-gap/</a><p data-notion-block-id=\\"1bfe548d-8a8e-80e3-835f-c791d2764ebd\\">Flexbox\uc5d0\uc11c \uc77c\ubd80\ubd84\ub9cc gap\uc758 \uac12\uc744 \ubc14\uafd4\uc57c \ud560 \ub54c \uc5b4\ub5bb\uac8c \ucf54\ub4dc\ub97c \ubc14\uafc0\uae4c\uc5d0 \ub300\ud55c \uc5ec\ub7ec \ubc29\uc2dd\uc744 \uc18c\uac1c\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-802d-8fdb-f79713596c44\\" id=\\"1bfe548d-8a8e-802d-8fdb-f79713596c44\\">\ube0c\ub77c\uc6b0\uc800 \uc90c \uac10\uc9c0\ud558\uae30</h2><a href=\\"https://www.kirupa.com/javascript/detecting_browser_zoom_changes.htm\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.kirupa.com/javascript/detecting_browser_zoom_changes.htm</a><p data-notion-block-id=\\"1c2e548d-8a8e-8056-99d0-c074910d8aa5\\">\ube0c\ub77c\uc6b0\uc800\ub97c \ud655\ub300/\ucd95\uc18c\ud558\ub294 \uc0ac\ub78c\uc740 \uc885\uc885 \uc788\uc9c0\ub9cc \ube0c\ub77c\uc6b0\uc800\uc5d0 zoom \uc774\ubca4\ud2b8\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ubc14\ub2d0\ub77c \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\ub85c \uc90c \ubc30\uc728\uc744 \ud655\uc778\ud558\ub294 \ucf54\ub4dc\ub97c \ub9cc\ub4e4\uace0 \uce5c\uc808\ud558\uac8c \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-80f7-889b-dbbad80456f3\\" id=\\"1bfe548d-8a8e-80f7-889b-dbbad80456f3\\">Zod, \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0</h2><a href=\\"https://didoesdigital.com/blog/zod-overview/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://didoesdigital.com/blog/zod-overview/</a><p data-notion-block-id=\\"1bfe548d-8a8e-804d-b89a-fe724f94ac6d\\">zod\uac00 \ubb34\uc5c7\uc778\uc9c0\uc5d0\uc11c\ubd80\ud130 zod\uc758 \uc0ac\uc6a9\ubc95\uc744 \uac04\ub2e8\ud558\uac8c \ubcf4\uc5ec\uc8fc\ub294 \ud29c\ud1a0\ub9ac\uc5bc\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1bfe548d-8a8e-8049-98ef-dd5678e39e91\\" id=\\"1bfe548d-8a8e-8049-98ef-dd5678e39e91\\">\uc0c8 \uce5c\uad6c\ub4e4</h2><a href=\\"https://valibot.dev/blog/valibot-v1-the-1-kb-schema-library/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://valibot.dev/blog/valibot-v1-the-1-kb-schema-library/</a><p data-notion-block-id=\\"1bfe548d-8a8e-80ea-a5f2-fed3f98ab4b9\\">\ud2b8\ub9ac\uc170\uc774\ud0b9 \uac00\ub2a5\ud55c \uc720\ud6a8\uc131 \uac80\uc0ac \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 Valibot\uc774 1\ubc84\uc804\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://socket.dev/blog/oxlint-now-in-beta-with-500-built-in-rules-2X-faster-javascript-linting\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://socket.dev/blog/oxlint-now-in-beta-with-500-built-in-rules-2X-faster-javascript-linting</a><p data-notion-block-id=\\"1bfe548d-8a8e-8028-a94d-f87dbbe2d478\\">Rust\uae30\ubc18\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 Oxlint\uac00 \ubca0\ud0c0\ubc84\uc804\uc73c\ub85c \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4. ESLint\ubcf4\ub2e4 2\ubc30 \ube60\ub974\ub2e4\uace0 \ud558\ub124\uc694.</p><a href=\\"https://rsdoctor.dev/blog/release/release-note-1_0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rsdoctor.dev/blog/release/release-note-1_0</a><p data-notion-block-id=\\"1bfe548d-8a8e-80c9-9f15-e5ea3b2e7bbc\\">Rspack\uacfc Webpack\uc758 \ube4c\ub4dc \uacfc\uc815\uc744 \ubd84\uc11d\ud558\ub294 \ub3c4\uad6c\uc778 Rsdoctor\uac00 1\ubc84\uc804\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://nuxt.com/blog/v3-16\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nuxt.com/blog/v3-16</a><p data-notion-block-id=\\"1bfe548d-8a8e-8064-ad5d-e24c944ecd3e\\">\uc5ec\ub7ec\uac00\uc9c0 \uae30\ub2a5\uc744 \ub2f4\uc740 Nuxt \uc0c8 \ubc84\uc804\uc774 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4. LazyComponent\ub97c hydration \ud0c0\uc774\ubc0d\uc744 \uc815\ud560 \uc218 \uc788\ub294 \uae30\ub2a5\uc774 \ub208\uc5d0 \ub744\ub124\uc694.</p><a href=\\"https://motion.dev/blog/introducing-motion-for-vue\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://motion.dev/blog/introducing-motion-for-vue</a><p data-notion-block-id=\\"1bfe548d-8a8e-801b-8626-c640baa09482\\">framer-motion\uc73c\ub85c \ub9ce\uc774 \uc54c\ub824\uc9c4 motion\ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 vue\ubc84\uc804\uc774 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://node-modules.dev/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://node-modules.dev/</a><p data-notion-block-id=\\"1bfe548d-8a8e-8050-b081-ef209efb946f\\">Web container\ub97c \uc0ac\uc6a9\ud574\uc11c node_modules\uc758 \ud06c\uae30\uc640 \uc5b4\ub5bb\uac8c \uc758\uc874\uc131\uc744 \ub744\uace0\uc788\ub294\uc9c0 \uc5ec\ub7ec\uac00\uc9c0 \ud615\ud0dc\ub85c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><a href=\\"https://www.openstatus.dev/blog/live-mode-infinite-query\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.openstatus.dev/blog/live-mode-infinite-query</a><p data-notion-block-id=\\"1bfe548d-8a8e-807f-bd8e-fc6b5c034e42\\">Infinite Query\uc758 UX\ub97c \ub354 \uc88b\uac8c, \ub354 \uc27d\uac8c \uad6c\ud604\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c0\uc6d0\ud558\ub294 Live mode\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/software-mansion/react-native-reanimated/discussions/7264\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/software-mansion/react-native-reanimated/discussions/7264</a><p data-notion-block-id=\\"1bfe548d-8a8e-80b6-a740-e43898a05919\\">\uba40\ud2f0 \uc2a4\ub808\ub4dc\uac00 \uac00\ub2a5\ud558\ub3c4\ub85d \ud558\ub294 React Native Worklets\uc5d0 \ub300\ud574 \uc758\ub17c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.callstack.com/blog/were-building-a-new-react-native-framework\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/were-building-a-new-react-native-framework</a><p data-notion-block-id=\\"1bfe548d-8a8e-803c-8507-ee215e07392c\\">React Native \uae00\uc744 \ub9ce\uc774 \uae30\uace0\ud558\ub358 Callstack \ud68c\uc0ac\uc5d0\uc11c \uc0c8\ub85c\uc6b4 RN \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ub9cc\ub4e4\uace0 \uc788\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"1c2e548d-8a8e-8060-9c30-eb17e60a872e\\"></p>"}')}}]);